-- Postflare — initial schema (D1 / SQLite).
-- Timestamps are ISO-8601 UTC strings generated by the application.
-- Soft deletion uses a nullable `deleted_at` column where appropriate.

PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------------------
-- Identity & workspace
-- ---------------------------------------------------------------------------

CREATE TABLE users (
  id            TEXT PRIMARY KEY,
  email         TEXT NOT NULL UNIQUE,
  name          TEXT NOT NULL,
  avatar_url    TEXT,
  password_hash TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);

CREATE TABLE sessions (
  id           TEXT PRIMARY KEY,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash   TEXT NOT NULL UNIQUE,
  expires_at   TEXT NOT NULL,
  last_seen_at TEXT NOT NULL,
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_sessions_user ON sessions(user_id);

CREATE TABLE workspaces (
  id         TEXT PRIMARY KEY,
  name       TEXT NOT NULL,
  slug       TEXT NOT NULL UNIQUE,
  timezone   TEXT NOT NULL DEFAULT 'UTC',
  plan       TEXT NOT NULL DEFAULT 'free',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL
);

CREATE TABLE workspace_members (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id      TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role         TEXT NOT NULL DEFAULT 'editor',
  created_at   TEXT NOT NULL,
  UNIQUE (workspace_id, user_id)
);
CREATE INDEX idx_members_user ON workspace_members(user_id);
CREATE INDEX idx_members_workspace ON workspace_members(workspace_id);

CREATE TABLE workspace_invitations (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  email        TEXT NOT NULL,
  role         TEXT NOT NULL DEFAULT 'editor',
  token        TEXT NOT NULL UNIQUE,
  status       TEXT NOT NULL DEFAULT 'pending',
  expires_at   TEXT NOT NULL,
  created_at   TEXT NOT NULL
);

CREATE TABLE workspace_settings (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL UNIQUE REFERENCES workspaces(id) ON DELETE CASCADE,
  settings_json TEXT NOT NULL DEFAULT '{}',
  updated_at   TEXT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Integrations, credentials & accounts
-- ---------------------------------------------------------------------------

CREATE TABLE integration_credentials (
  id             TEXT PRIMARY KEY,
  workspace_id   TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  provider_id    TEXT NOT NULL,
  ciphertext     TEXT NOT NULL,
  key_version    INTEGER NOT NULL DEFAULT 1,
  field_keys_json TEXT NOT NULL DEFAULT '[]',
  masked_json    TEXT NOT NULL DEFAULT '{}',
  created_at     TEXT NOT NULL,
  updated_at     TEXT NOT NULL,
  UNIQUE (workspace_id, provider_id)
);

CREATE TABLE connected_accounts (
  id               TEXT PRIMARY KEY,
  workspace_id     TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  provider_id      TEXT NOT NULL,
  credentials_id   TEXT REFERENCES integration_credentials(id) ON DELETE SET NULL,
  external_id      TEXT,
  account_name     TEXT NOT NULL,
  username         TEXT,
  avatar_url       TEXT,
  status           TEXT NOT NULL DEFAULT 'connected',
  is_default       INTEGER NOT NULL DEFAULT 0,
  token_expires_at TEXT,
  last_synced_at   TEXT,
  last_error       TEXT,
  created_at       TEXT NOT NULL,
  updated_at       TEXT NOT NULL
);
CREATE INDEX idx_accounts_workspace ON connected_accounts(workspace_id, provider_id);

CREATE TABLE oauth_states (
  id            TEXT PRIMARY KEY,
  workspace_id  TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  provider_id   TEXT NOT NULL,
  state         TEXT NOT NULL UNIQUE,
  code_verifier TEXT,
  redirect_uri  TEXT NOT NULL,
  account_name  TEXT,
  expires_at    TEXT NOT NULL,
  used          INTEGER NOT NULL DEFAULT 0,
  created_at    TEXT NOT NULL
);

CREATE TABLE token_refresh_logs (
  id         TEXT PRIMARY KEY,
  account_id TEXT NOT NULL REFERENCES connected_accounts(id) ON DELETE CASCADE,
  status     TEXT NOT NULL,
  error      TEXT,
  created_at TEXT NOT NULL
);

CREATE TABLE webhook_endpoints (
  id                 TEXT PRIMARY KEY,
  workspace_id       TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  provider_id        TEXT NOT NULL,
  account_id         TEXT,
  url                TEXT NOT NULL,
  secret_ciphertext  TEXT,
  created_at         TEXT NOT NULL
);

CREATE TABLE webhook_events (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  provider_id  TEXT NOT NULL,
  account_id   TEXT,
  event_id     TEXT NOT NULL,
  event_type   TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  processed    INTEGER NOT NULL DEFAULT 0,
  received_at  TEXT NOT NULL,
  UNIQUE (provider_id, event_id)
);

-- ---------------------------------------------------------------------------
-- Publishing
-- ---------------------------------------------------------------------------

CREATE TABLE posts (
  id            TEXT PRIMARY KEY,
  workspace_id  TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  status        TEXT NOT NULL DEFAULT 'draft',
  scheduled_for TEXT,
  campaign_id   TEXT,
  created_by    TEXT NOT NULL,
  deleted_at    TEXT,
  created_at    TEXT NOT NULL,
  updated_at    TEXT NOT NULL
);
CREATE INDEX idx_posts_workspace ON posts(workspace_id, status);
CREATE INDEX idx_posts_scheduled ON posts(scheduled_for) WHERE scheduled_for IS NOT NULL AND status IN ('scheduled', 'approved');

CREATE TABLE post_variants (
  id          TEXT PRIMARY KEY,
  post_id     TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  provider_id TEXT NOT NULL,
  text        TEXT NOT NULL DEFAULT '',
  title       TEXT,
  link        TEXT,
  created_at  TEXT NOT NULL
);
CREATE INDEX idx_variants_post ON post_variants(post_id);

CREATE TABLE post_variant_media (
  id         TEXT PRIMARY KEY,
  variant_id TEXT NOT NULL REFERENCES post_variants(id) ON DELETE CASCADE,
  media_id   TEXT NOT NULL,
  position   INTEGER NOT NULL DEFAULT 0
);
CREATE INDEX idx_variant_media ON post_variant_media(variant_id);

CREATE TABLE post_accounts (
  id              TEXT PRIMARY KEY,
  post_id         TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  account_id      TEXT NOT NULL REFERENCES connected_accounts(id) ON DELETE CASCADE,
  provider_id     TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'draft',
  remote_id       TEXT,
  error           TEXT,
  published_at    TEXT,
  idempotency_key TEXT,
  UNIQUE (post_id, account_id)
);
CREATE INDEX idx_post_accounts_post ON post_accounts(post_id);

CREATE TABLE publishing_jobs (
  id              TEXT PRIMARY KEY,
  post_id         TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  account_id      TEXT NOT NULL REFERENCES connected_accounts(id) ON DELETE CASCADE,
  run_at          TEXT NOT NULL,
  status          TEXT NOT NULL DEFAULT 'queued',
  attempts        INTEGER NOT NULL DEFAULT 0,
  max_attempts    INTEGER NOT NULL DEFAULT 5,
  last_error      TEXT,
  idempotency_key TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  updated_at      TEXT NOT NULL
);
CREATE INDEX idx_jobs_due ON publishing_jobs(status, run_at);
CREATE INDEX idx_jobs_post ON publishing_jobs(post_id);

CREATE TABLE publishing_attempts (
  id             TEXT PRIMARY KEY,
  job_id         TEXT NOT NULL REFERENCES publishing_jobs(id) ON DELETE CASCADE,
  post_id        TEXT NOT NULL,
  account_id     TEXT NOT NULL,
  provider_id    TEXT NOT NULL,
  status         TEXT NOT NULL,
  response_summary TEXT,
  error          TEXT,
  created_at     TEXT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Media
-- ---------------------------------------------------------------------------

CREATE TABLE media_folders (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  parent_id    TEXT,
  created_at   TEXT NOT NULL
);

CREATE TABLE media_assets (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  folder_id    TEXT,
  filename     TEXT NOT NULL,
  mime_type    TEXT NOT NULL,
  size         INTEGER NOT NULL,
  width        INTEGER,
  height       INTEGER,
  duration     REAL,
  r2_key       TEXT NOT NULL,
  deleted_at   TEXT,
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_media_workspace ON media_assets(workspace_id);

CREATE TABLE media_tags (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  UNIQUE (workspace_id, name)
);

CREATE TABLE media_asset_tags (
  id       TEXT PRIMARY KEY,
  media_id TEXT NOT NULL REFERENCES media_assets(id) ON DELETE CASCADE,
  tag_id   TEXT NOT NULL REFERENCES media_tags(id) ON DELETE CASCADE
);

-- ---------------------------------------------------------------------------
-- Inbox & contacts
-- ---------------------------------------------------------------------------

CREATE TABLE contacts (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         TEXT,
  username     TEXT,
  email        TEXT,
  phone        TEXT,
  avatar_url   TEXT,
  consent      TEXT NOT NULL DEFAULT 'unknown',
  assigned_to  TEXT,
  deleted_at   TEXT,
  created_at   TEXT NOT NULL,
  updated_at   TEXT NOT NULL
);
CREATE INDEX idx_contacts_workspace ON contacts(workspace_id);

CREATE TABLE contact_profiles (
  id          TEXT PRIMARY KEY,
  contact_id  TEXT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  provider_id TEXT NOT NULL,
  external_id TEXT NOT NULL,
  username    TEXT,
  avatar_url  TEXT,
  created_at  TEXT NOT NULL,
  UNIQUE (provider_id, external_id)
);

CREATE TABLE contact_tags (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  UNIQUE (workspace_id, name)
);

CREATE TABLE contact_tag_links (
  id         TEXT PRIMARY KEY,
  contact_id TEXT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  tag_id     TEXT NOT NULL REFERENCES contact_tags(id) ON DELETE CASCADE,
  UNIQUE (contact_id, tag_id)
);

CREATE TABLE contact_custom_fields (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  type         TEXT NOT NULL DEFAULT 'text',
  UNIQUE (workspace_id, name)
);

CREATE TABLE contact_custom_field_values (
  id         TEXT PRIMARY KEY,
  contact_id TEXT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  field_id   TEXT NOT NULL REFERENCES contact_custom_fields(id) ON DELETE CASCADE,
  value      TEXT,
  UNIQUE (contact_id, field_id)
);

CREATE TABLE conversations (
  id                   TEXT PRIMARY KEY,
  workspace_id         TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  account_id           TEXT REFERENCES connected_accounts(id) ON DELETE SET NULL,
  provider_id          TEXT NOT NULL,
  contact_id           TEXT REFERENCES contacts(id) ON DELETE SET NULL,
  external_id          TEXT,
  status               TEXT NOT NULL DEFAULT 'open',
  unread_count         INTEGER NOT NULL DEFAULT 0,
  assigned_to          TEXT,
  priority             TEXT NOT NULL DEFAULT 'normal',
  labels_json          TEXT NOT NULL DEFAULT '[]',
  last_message_preview TEXT,
  last_message_at      TEXT,
  created_at           TEXT NOT NULL,
  updated_at           TEXT NOT NULL
);
CREATE INDEX idx_conversations_workspace ON conversations(workspace_id, status);
CREATE UNIQUE INDEX idx_conversations_external ON conversations(provider_id, external_id) WHERE external_id IS NOT NULL;

CREATE TABLE conversation_participants (
  id              TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  contact_id      TEXT NOT NULL REFERENCES contacts(id) ON DELETE CASCADE,
  role            TEXT NOT NULL DEFAULT 'participant'
);

CREATE TABLE messages (
  id              TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  direction       TEXT NOT NULL,
  body            TEXT,
  media_url       TEXT,
  sender_name     TEXT,
  external_id     TEXT,
  sent_at         TEXT NOT NULL,
  created_at      TEXT NOT NULL
);
CREATE INDEX idx_messages_conversation ON messages(conversation_id, sent_at);

CREATE TABLE message_attachments (
  id         TEXT PRIMARY KEY,
  message_id TEXT NOT NULL REFERENCES messages(id) ON DELETE CASCADE,
  media_id   TEXT,
  url        TEXT,
  type       TEXT NOT NULL
);

CREATE TABLE conversation_assignments (
  id              TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  user_id         TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  assigned_by     TEXT NOT NULL,
  created_at      TEXT NOT NULL
);

CREATE TABLE internal_notes (
  id              TEXT PRIMARY KEY,
  conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  author_id       TEXT NOT NULL,
  body            TEXT NOT NULL,
  created_at      TEXT NOT NULL
);

CREATE TABLE quick_replies (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  title        TEXT NOT NULL,
  body         TEXT NOT NULL,
  created_at   TEXT NOT NULL
);

-- ---------------------------------------------------------------------------
-- Automation
-- ---------------------------------------------------------------------------

CREATE TABLE automations (
  id                 TEXT PRIMARY KEY,
  workspace_id       TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name               TEXT NOT NULL,
  status             TEXT NOT NULL DEFAULT 'draft',
  trigger_type       TEXT NOT NULL,
  trigger_config_json TEXT NOT NULL DEFAULT '{}',
  published_version  INTEGER,
  created_by         TEXT NOT NULL,
  deleted_at         TEXT,
  created_at         TEXT NOT NULL,
  updated_at         TEXT NOT NULL
);
CREATE INDEX idx_automations_workspace ON automations(workspace_id);

CREATE TABLE automation_versions (
  id              TEXT PRIMARY KEY,
  automation_id   TEXT NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
  version         INTEGER NOT NULL,
  definition_json TEXT NOT NULL,
  created_by      TEXT NOT NULL,
  created_at      TEXT NOT NULL,
  UNIQUE (automation_id, version)
);

CREATE TABLE automation_executions (
  id              TEXT PRIMARY KEY,
  workspace_id    TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  automation_id   TEXT NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
  version         INTEGER NOT NULL,
  status          TEXT NOT NULL DEFAULT 'running',
  current_node_id TEXT,
  input_json      TEXT NOT NULL DEFAULT '{}',
  context_json    TEXT NOT NULL DEFAULT '{}',
  error           TEXT,
  started_at      TEXT NOT NULL,
  finished_at     TEXT
);
CREATE INDEX idx_executions_workspace ON automation_executions(workspace_id, started_at);

CREATE TABLE automation_execution_steps (
  id           TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL REFERENCES automation_executions(id) ON DELETE CASCADE,
  node_id      TEXT NOT NULL,
  node_type    TEXT NOT NULL,
  status       TEXT NOT NULL,
  input_json   TEXT,
  output_json  TEXT,
  error        TEXT,
  started_at   TEXT NOT NULL,
  finished_at  TEXT
);

CREATE TABLE automation_scheduled_resumes (
  id           TEXT PRIMARY KEY,
  execution_id TEXT NOT NULL REFERENCES automation_executions(id) ON DELETE CASCADE,
  node_id      TEXT NOT NULL,
  resume_at    TEXT NOT NULL,
  status       TEXT NOT NULL DEFAULT 'pending'
);
CREATE INDEX idx_resumes_due ON automation_scheduled_resumes(status, resume_at);

-- ---------------------------------------------------------------------------
-- Analytics
-- ---------------------------------------------------------------------------

CREATE TABLE account_metrics (
  id          TEXT PRIMARY KEY,
  account_id  TEXT NOT NULL REFERENCES connected_accounts(id) ON DELETE CASCADE,
  provider_id TEXT NOT NULL,
  metric_date TEXT NOT NULL,
  metrics_json TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  UNIQUE (account_id, provider_id, metric_date)
);

CREATE TABLE post_metrics (
  id          TEXT PRIMARY KEY,
  post_id     TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  account_id  TEXT NOT NULL REFERENCES connected_accounts(id) ON DELETE CASCADE,
  provider_id TEXT NOT NULL,
  metric_date TEXT NOT NULL,
  metrics_json TEXT NOT NULL,
  created_at  TEXT NOT NULL,
  UNIQUE (post_id, account_id, provider_id, metric_date)
);

-- ---------------------------------------------------------------------------
-- Collaboration
-- ---------------------------------------------------------------------------

CREATE TABLE campaigns (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  name         TEXT NOT NULL,
  description  TEXT,
  objective    TEXT,
  start_date   TEXT,
  end_date     TEXT,
  created_by   TEXT NOT NULL,
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_campaigns_workspace ON campaigns(workspace_id);

CREATE TABLE campaign_posts (
  id          TEXT PRIMARY KEY,
  campaign_id TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  post_id     TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  UNIQUE (campaign_id, post_id)
);

CREATE TABLE campaign_automations (
  id            TEXT PRIMARY KEY,
  campaign_id   TEXT NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  automation_id TEXT NOT NULL REFERENCES automations(id) ON DELETE CASCADE,
  UNIQUE (campaign_id, automation_id)
);

CREATE TABLE approvals (
  id            TEXT PRIMARY KEY,
  workspace_id  TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  post_id       TEXT NOT NULL REFERENCES posts(id) ON DELETE CASCADE,
  requested_by  TEXT NOT NULL,
  reviewer_id   TEXT,
  status        TEXT NOT NULL DEFAULT 'pending',
  comment       TEXT,
  created_at    TEXT NOT NULL,
  resolved_at   TEXT
);
CREATE INDEX idx_approvals_workspace ON approvals(workspace_id, status);

CREATE TABLE approval_history (
  id          TEXT PRIMARY KEY,
  approval_id TEXT NOT NULL REFERENCES approvals(id) ON DELETE CASCADE,
  actor_id    TEXT NOT NULL,
  action      TEXT NOT NULL,
  comment     TEXT,
  created_at  TEXT NOT NULL
);

CREATE TABLE notifications (
  id           TEXT PRIMARY KEY,
  workspace_id TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  user_id      TEXT,
  type         TEXT NOT NULL,
  title        TEXT NOT NULL,
  body         TEXT,
  is_read      INTEGER NOT NULL DEFAULT 0,
  created_at   TEXT NOT NULL
);
CREATE INDEX idx_notifications_workspace ON notifications(workspace_id, is_read);

CREATE TABLE audit_logs (
  id            TEXT PRIMARY KEY,
  workspace_id  TEXT NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE,
  actor_id      TEXT,
  action        TEXT NOT NULL,
  resource_type TEXT NOT NULL,
  resource_id   TEXT,
  metadata_json TEXT NOT NULL DEFAULT '{}',
  created_at    TEXT NOT NULL
);
CREATE INDEX idx_audit_workspace ON audit_logs(workspace_id, created_at);